int manage_sound_timer(struct file *file, struct snd_timer_select __user *tselect) {
    struct snd_timer *timer = NULL;
    struct snd_timer_id tid;
    int err = 0;

    if (!file || !tselect) {
        return -EINVAL;
    }

    if (copy_from_user(&tid, tselect, sizeof(tid))) {
        return -EFAULT;
    }

    if (tid.card < 0 || tid.device < 0 || tid.subdevice < 0) {
        return -EINVAL;
    }

    timer = kzalloc(sizeof(*timer), GFP_KERNEL);
    if (!timer) {
        return -ENOMEM;
    }

    timer->private_data = file->private_data;

    timer->queues = kzalloc(sizeof(*timer->queues) * MAX_TIMER_QUEUES, GFP_KERNEL);
    if (!timer->queues) {
        err = -ENOMEM;
        goto error_cleanup;
    }

    timer->queue_count = MAX_TIMER_QUEUES;
    timer->flags = SNDRV_TIMER_FAST;

    timer->callback = timer_callback;
    timer->private_free = timer_private_free;

    file->private_data = timer;

    return 0;

error_cleanup:
    if (timer) {
        kfree(timer->queues);
        kfree(timer);
    }
    return err;
}
